sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Set priority based on feedback_type
    if (current.feedback_type == "complaint" || current.feedback_type == "request") {
        current.priority = "high";
    } else if (current.feedback_type == "suggestion") {
        current.priority = "medium";
    } else if (current.feedback_type == "feedback") {
        current.priority = "low";
    }

    // Map service_type to department name
    var deptName = "";
    switch (current.service_type) {
        case "Water Supply":
            deptName = "Water Supply";
            break;
        case "Electricity / Power":
            deptName = "Electricity / Power";
            break;
        case "Gas Supply":
            deptName = "Gas Supply";
            break;
        case "Sanitation / Drainage":
            deptName = "Sanitation / Drainage";
            break;
        case "Street Lighting":
            deptName = "Street Lighting";
            break;
        case "Police / Law & Order":
            deptName = "Police / Law & Order";
            break;
        case "Fire & Safety":
            deptName = "Fire & Safety";
            break;
        case "Ambulance Services":
            deptName = "Ambulance Services";
            break;
        case "Road / Street Maintenance":
            deptName = "Road / Street Maintenance";
            break;
        case "Road Safety / Signals":
            deptName = "Road Safety / Signals";
            break;
        case "Natural Disaster Response":
            deptName = "Natural Disaster Response";
            break;
        case "Schools / Colleges":
            deptName = "Schools / Colleges";
            break;
        case "Welfare Schemes":
            deptName = "Welfare Schemes";
            break;
        case "Public Transport":
            deptName = "Public Transport";
            break;
        case "Public Toilets":
            deptName = "Public Toilets";
            break;
        case "Garbage collection":
            deptName = "Garbage collection";
            break;
        default:
            deptName = "";
    }

    // Assign department by lookup
    if (deptName) {
        var dept = new GlideRecord("cmn_department");
        dept.addQuery("name", deptName);
        dept.query();
        if (dept.next()) {
            current.assigned_dept = dept.sys_id;  // ✅ assign sys_id, not name
        }
    }

})(current, previous);
